startConnection:
function startConnection(reqChanel) {
    if (!reqChanel.startsWith(sendMsg)) {
        reqChanel = sendMsg + reqChanel;
    }

    connection = new signalR.HubConnectionBuilder()
        .withUrl(important_data.hubUrl, {
            transport: signalR.HttpTransportType.ServerSentEvents,
        })
        .withAutomaticReconnect()
        .build();

    connection
        .start()
        .then(() => {
            console.log("SignalR connected");
            if (reqChanel) {
                joinGroup(reqChanel);
            }
        })
        .catch((err) => {
            console.log("SignalR connection error:", err);

            setTimeout(() => startConnection(reqChanel), 250);
        });

    connection.onclose(() => {
        console.log("onclose");
    });

    connection.onreconnecting(() => {
        console.log("reconncect");
    });

    connection.onreconnected(() => {
        if (reqChanel) {
            joinGroup(reqChanel); // Rejoin the group after reconnection
        }
    });

    connection.on("ReceiveMessage", function (message) {
        var split_status = message.split("|");
        let hid_multi = document.getElementById("hid_multi");
        const hasHidMultiValue = hid_multi && hid_multi.value.trim() !== "";

        if (split_status[0] == "success") {
            $("#WP_Payment").modal("hide");
            $("#text_status_payment").addClass("lang_lbl_payment_complete");
            const img = document.createElement("img");
            img.src = "/assets/images/success.jpg";
            img.className = "successimg";
            $("#img_payment").html(img);

            $("#success_payment").modal("show");
            leaveGroup(reqChanel);

            let defaultId = core_datas?.default_profile?.user_type_id;
            let currentId = core_datas?.current_profile?.user_type_id;
            let isRenewal = localStorage.getItem("form_type_id") === "MT_63_2_AGN_RENEWAL";
            let hasNoCollateral = localStorage.getItem("collateral") !== "collateral";

            // ตรงตาม 2 case เดิม
            let allow =
                (defaultId === "5" && ["2", "4"].includes(currentId)) ||
                (["2", "4"].includes(defaultId));

            if (allow && isRenewal && hasNoCollateral && !group_id_value && !hasHidMultiValue) {

                const html = `
                    <div class="row justify-content-between mt-3 div_info only_MT_63_2_AGN_RENEWAL" style="border: 1px solid #E24C86;border-radius:13px !important;">
                      <div class="col-auto" style="display: flex;align-items: start;">
                        <div style="display:flex; align-items:center;">
                          <img src="/assets/images/Vector.png" style="width:30px; height:auto; margin-right:12px;">

                          <div style="color:#11111f;">
                            <span style="font-weight:700;font-size: 15px;">มีรายการที่ต้องชำระค่าหลักประกัน</span><br>
                            <span style="color:#E24C86;font-size: 13px;">หมายเหตุ : ท่านสามารถดูรายการทั้งหมด ได้ที่แท็บ “รายการชำระเงิน”</span>
                          </div>
